import re, subprocess, sys, yaml
commit = "c29ca56724e96ce620ef44975f045bbb083fd112"
path, out_masked, out_deferred = sys.argv[1], sys.argv[2], sys.argv[3]
raw = subprocess.run(["git", "show", f"{commit}:{path}"], capture_output=True, check=True).stdout
doc = yaml.safe_load(raw)
PAT = re.compile(r"C-4|C-5|C-6|sweep|false_pass|false-pass|Monte Carlo|pattern|calibrat", re.I)
masked, deferred = [], []
def walk(x, p):
    if isinstance(x, dict):
        for k, v in x.items():
            walk(v, p + [str(k)])
    elif isinstance(x, list):
        for i, v in enumerate(x):
            walk(v, p + [str(i)])
    else:
        s = "" if x is None else str(x)
        key = ".".join(p)
        if PAT.search(s) or PAT.search(key):
            masked.append(f"{key}: [DEFERRED]")
            deferred.append(f"{key}: {s}")
        else:
            masked.append(f"{key}: {s}")
walk(doc, [])
open(out_masked, "w").write("\n".join(masked) + "\n")
open(out_deferred, "w").write("\n".join(deferred) + "\n")
print(path, "leaves", len(masked), "deferred", len(deferred))

