"""TASK-20261002-aba8f9 own false-pass sweep, version 2 (J3 attack (i)).

Review computation, written by the red team from the contract's statistic
definitions BEFORE opening the producer's false_pass_sweep, gen_values,
coverage_values, outcome_patterns or any C-4/C-5/C-6 output. Imports the
committed binstd_core.py (sha256 f22babf6...038e) and dry-calls pure
functions only. Deterministic; no random number is drawn.

Each row is a one-parameter family x -> values dict (x >= 0 the deviation
size, x = 0 the model point) built from the contract's own definitions, with
the code's identities enforced (n_att = n_t a_bar; n_dec = n_att x mean count;
KR = rho_rel a_pred / a_bar; FR = a_bar / a_pred; d_sigma from KR). The
smallest deviation the NAMED statistic flags is found by bisection on that
statistic's own gate_table row evaluated in the final dict, so thresholds
that move with the deviation (n_att, n_dec) are self-consistent. The point
recorded is the bisection's upper end (flagged), within 1e-9 relative.
"""
import json
import math
import sys
import time

S = sys.argv[1]
sys.path.insert(0, S + "/impl")
import binstd_core as bc  # noqa: E402

N_T = 1365


def comp_zn():
    return dict(B=128, mu=bc.MU_ZN_DESIGN, blocks=((128, 256 ** 2),), h=1, sigma=256)


def comp_ord(eps=0.0):
    n0 = int(round(256 * (1 + eps)))
    n1 = 512 - n0
    return dict(B=512, mu=1.0, blocks=((n0, (2 * n0) ** 2), (n1, (2 * n1) ** 2)), h=2, sigma=1024)


def comp_kob(e02=0.0, e13=0.0):
    n13 = int(round(256 * (1 - e13)))
    rest = 512 - n13
    n0 = int(round(rest / 2 * (1 + e02)))
    n2 = rest - n0
    return dict(B=512, mu=1.0, blocks=((n0, (2 * n0) ** 2), (n2, (2 * n2) ** 2), (n13, 2 * n13 ** 2)),
                h=4, sigma=1024)


def model_values(c):
    cm = bc.cell_model(c["B"], c["mu"], c["blocks"], c["h"], c["sigma"])
    v = {"B": c["B"], "mu": c["mu"], "h": c["h"], "sigma": c["sigma"],
         "blocks": [list(b) for b in c["blocks"]], "f": cm["f"], "mu_eff": cm["mu_eff"],
         "delta_hat": cm["delta_pred"], "delta_blocks": list(cm["delta_k"]),
         "u_hat": cm["u_pred"], "n_t": N_T, "a_bar": cm["a_pred"], "kappa_hat": cm["kappa_pred"],
         "rho_rel": 1.0, "d_sigma_extra": 0.0, "mbar": cm["mu_eff"]}
    return finish(v)


def finish(v):
    cm = bc.model_of(v)
    v["n_att"] = v["n_t"] * v["a_bar"]
    v["n_dec"] = v["n_att"] * v["mbar"]
    v["KR"] = v["rho_rel"] * cm["a_pred"] / v["a_bar"]
    v["FR"] = v["a_bar"] / cm["a_pred"]
    v["d_sigma"] = (bc.sigma_pred(v["KR"] * cm["K_pred"], bc.L_IC)
                    - bc.sigma_pred(cm["K_pred"], bc.L_IC) + v["d_sigma_extra"])
    return v


def copyv(v, **kw):
    w = dict(v)
    w["delta_blocks"] = list(v["delta_blocks"])
    w.update(kw)
    return finish(w)


def u_of_blocks(m, db):
    cm = bc.model_of(m)
    return sum(wk * x * x for wk, x in zip(cm["w"], db)) if len(db) > 1 else db[0] ** 2


def p_of(m, u):
    return -math.expm1(-bc.model_of(m)["mu_eff"] * u)


# --------------------------------------------------------------- families
def fam_delta(m, x, sgn, coupled):
    sc = 1 + sgn * x
    db = [d * sc for d in m["delta_blocks"]]
    kw = {"delta_hat": m["delta_hat"] * sc, "delta_blocks": db}
    if coupled:
        u = u_of_blocks(m, db)
        kw.update(u_hat=u, a_bar=1 / p_of(m, u))
    return copyv(m, **kw)


def fam_u(m, x, sgn, coupled):
    u = m["u_hat"] * (1 + sgn * x)
    kw = {"u_hat": u}
    if coupled:
        kw["a_bar"] = 1 / p_of(m, u)
    return copyv(m, **kw)


def fam_a(m, x, sgn):
    return copyv(m, a_bar=m["a_bar"] * (1 + sgn * x))


def fam_kappa(m, x, sgn):
    return copyv(m, kappa_hat=m["kappa_hat"] * (1 + sgn * x))


def fam_rho(m, x, sgn):
    return copyv(m, rho_rel=math.exp(sgn * x))


def fam_dsig(m, x, sgn):
    return copyv(m, d_sigma_extra=sgn * x)


def count_law(kind, mu, d):
    """Count per attempt at MATCHED MEAN mu, coverage (1 - d)(1 - exp(-mu)).
    low/excess: support {0, 1, 2}; high: zero-inflated Poisson."""
    kt = (1 - d) * (-math.expm1(-mu))
    if kind in ("low", "excess"):
        q2, q1 = mu - kt, 2 * kt - mu
        q0 = 1 - q1 - q2
        if min(q0, q1, q2) < -1e-12:
            return None
        return kt, (lambda u: 1 - (q0 + q1 * (1 - u) + q2 * (1 - u) ** 2))
    lo, hi = 0.0, 0.999999
    for _ in range(200):
        z = (lo + hi) / 2
        if (1 - z) * (-math.expm1(-mu / (1 - z))) > kt:
            lo = z
        else:
            hi = z
    z = (lo + hi) / 2
    return (1 - z) * (-math.expm1(-mu / (1 - z))), (lambda u: (1 - z) * (-math.expm1(-mu * u / (1 - z))))


def fam_cov(m, x, sgn, kind, coupled):
    """sgn = +1 deficit of relative size x; sgn = -1 excess."""
    cm = bc.model_of(m)
    r = count_law("excess" if sgn < 0 else kind, cm["mu_eff"], sgn * x)
    if r is None:
        return None
    cov, puse = r
    if not coupled:
        return copyv(m, kappa_hat=cov)
    return copyv(m, kappa_hat=cov, rho_rel=cm["kappa_pred"] / cov, a_bar=1 / puse(m["u_hat"]))


def side_of(v, stat, zn):
    row = bc.gate_table(v, zn)[stat]
    return bc.side(*row)


def smallest_flagged(m, fam, stat, zn, xmax):
    v = fam(m, xmax)
    if v is None or side_of(v, stat, zn) == "pass":
        # shrink xmax to the feasible range, then test again
        lo_f, hi_f = 0.0, xmax
        for _ in range(80):
            mid = (lo_f + hi_f) / 2
            if fam(m, mid) is None:
                hi_f = mid
            else:
                lo_f = mid
        v = fam(m, lo_f)
        if v is None or side_of(v, stat, zn) == "pass":
            return None, lo_f
        xmax = lo_f
    lo, hi = 0.0, xmax
    for _ in range(200):
        mid = (lo + hi) / 2
        w = fam(m, mid)
        if w is not None and side_of(w, stat, zn) != "pass":
            hi = mid
        else:
            lo = mid
    return hi, None


def first_flag(m, fam, zn, xmax):
    """Smallest x at which ANY gate flags along the family, and which."""
    def anyflag(x):
        w = fam(m, x)
        if w is None:
            return None
        t = bc.gate_tests(w, zn)
        return [k for k, s in t.items() if s != "pass"]
    lo, hi = 0.0, xmax
    if fam(m, hi) is None:
        a, b = 0.0, xmax
        for _ in range(80):
            mid = (a + b) / 2
            if fam(m, mid) is None:
                b = mid
            else:
                a = mid
        hi = a
    f = anyflag(hi)
    if not f:
        return None, None
    for _ in range(200):
        mid = (lo + hi) / 2
        f = anyflag(mid)
        if f:
            hi = mid
        else:
            lo = mid
    return hi, anyflag(hi)


def classify(v, zn=None):
    t = bc.gate_tests(v, zn)
    return bc.classify_cell(t), sorted(k + ":" + s for k, s in t.items() if s != "pass"), \
        bc.yield_audit(v)["coverage_deficit"]


def cell_result(phi, deficit, ord_cell=False):
    c = {"certificates_ok": True, "coset": {"admitted": True},
         "reuse": {"phi": phi, "abandoned": 0, "yield_audit": {"coverage_deficit": deficit}, "gops_ok": True},
         "rho": {"h2_pass": True, "instrument_ok": True},
         "ctl6": {"ok": True}, "ir5": {"ic_reading_valid": True}}
    if ord_cell:
        c["null"] = {"discriminates": True}
    return c


def outcome(ord_c, kob_c, g1=True, zn_h2=True):
    rf = {"S0_pass": True, "G1_pass": g1, "IR1_fired": False, "IR2_fired": False,
          "IR6_fired": False, "IR7_fired": False}
    adm = {n: {r: True for r in bc.ADMISSION_RULES} for n in bc.BINARY_CELLS}
    aud = {n: {"relation_attempts_checked": 256, "targets_checked": 128, "discrepancies": 0}
           for n in bc.BINARY_CELLS}
    o = bc.stage2_outcome({"rho": {"h2_pass": zn_h2}}, {bc.ORD_CELL: ord_c, bc.KOB_CELL: kob_c}, rf, adm, aud)
    return o["H1"], o["H2"], o["contract"]


def route(dev, models):
    """dev: {'ZN': dict or None, 'ORD': ..., 'KOB': ...}; None = model point."""
    res = {}
    for cfg in ("both", "ord_only", "kob_only", "control_only"):
        use = {"ZN": models["ZN"], "ORD": models["ORD"], "KOB": models["KOB"]}
        if cfg in ("both", "ord_only") and dev["ORD"] is not None:
            use["ORD"] = dev["ORD"]
        if cfg in ("both", "kob_only") and dev["KOB"] is not None:
            use["KOB"] = dev["KOB"]
        if cfg == "control_only" and dev["ZN"] is not None:
            use["ZN"] = dev["ZN"]
        zc, zf, _ = classify(use["ZN"])
        oc, of_, od = classify(use["ORD"], use["ZN"])
        kc, kf, kd = classify(use["KOB"], use["ZN"])
        h1, h2, lab = outcome(cell_result(oc, od, True), cell_result(kc, kd), g1=(zc == "PASS"))
        res[cfg] = {"class": {"ORD": oc, "KOB": kc, "ZN": zc},
                    "fails": {"ORD": of_, "KOB": kf, "ZN": zf}, "deficit_flag": {"ORD": od, "KOB": kd},
                    "H1": h1, "H2": h2, "contract": lab}
    return res


def main():
    out = {"started_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "regimes": {}, "rows": []}
    regimes = {
        "nominal_f1": (comp_zn(), comp_ord(0.0), comp_kob(0.0, 0.0)),
        "f1.02_A": (comp_zn(), comp_ord(math.sqrt(0.02)), comp_kob(0.2, 0.0)),
        "f1.02_B": (comp_zn(), comp_ord(math.sqrt(0.02)), comp_kob(0.0, math.sqrt(0.02))),
        "f1.05_B": (comp_zn(), comp_ord(math.sqrt(0.05)), comp_kob(0.0, math.sqrt(0.05))),
        "f1.10_B": (comp_zn(), comp_ord(math.sqrt(0.10)), comp_kob(0.0, math.sqrt(0.10))),
    }
    fams = []
    for sgn, dn in ((-1, "low"), (+1, "high")):
        fams.append(("H1(b) determined-column law", "T_delta", dn, "isolated: delta only",
                     lambda m, x, s=sgn: fam_delta(m, x, s, False), 0.6))
        fams.append(("H1(b) determined-column law", "T_delta", dn, "coupled: u = sum w delta_k^2, a = 1/p(u)",
                     lambda m, x, s=sgn: fam_delta(m, x, s, True), 0.6))
        fams.append(("H1(b)/(c) determined-column law vs control", "T_cmp", dn,
                     "coupled delta family, read by T_cmp (binary cells only)",
                     lambda m, x, s=sgn: fam_delta(m, x, s, True), 0.6))
        fams.append(("H1(g) attempts law at u_pred", "AM2_FR", "low (FR high)" if sgn < 0 else "high (FR low)",
                     "coupled delta family, read by AM2",
                     lambda m, x, s=sgn: fam_delta(m, x, s, True), 0.6))
        fams.append(("H1(c) usable probability", "T_u", dn, "isolated: u only",
                     lambda m, x, s=sgn: fam_u(m, x, s, False), 0.6))
        fams.append(("H1(c) usable probability", "T_u", dn, "coupled: a = 1/p(u)",
                     lambda m, x, s=sgn: fam_u(m, x, s, True), 0.6))
        fams.append(("H1(d) attempts law", "T_a", "low (a high)" if sgn > 0 else "high (a low)",
                     "a_bar moved; KR, FR, d_sigma by identity",
                     lambda m, x, s=sgn: fam_a(m, x, s), 0.9))
        fams.append(("H1(e) target coverage", "T_kappa", dn, "isolated: kappa only (PTM-E form)",
                     lambda m, x, s=sgn: fam_kappa(m, x, s), 0.9))
        fams.append(("H1(f) relation-phase yield", "T_rho", "low (rho_rel high)" if sgn > 0 else "high (rho_rel low)",
                     "rho_rel moved; KR, d_sigma by identity",
                     lambda m, x, s=sgn: fam_rho(m, x, s), 2.0))
        fams.append(("H1(f) relation-phase yield via KR", "AM1_KR", "low (KR low)" if sgn < 0 else "high (KR high)",
                     "rho_rel family read by AM1",
                     lambda m, x, s=sgn: fam_rho(m, x, s), 2.0))
        fams.append(("H1(g) L-structure", "AM3_dsigma", "low" if sgn > 0 else "high", "isolated d_sigma",
                     lambda m, x, s=sgn: fam_dsig(m, x, s), 1.0))
    for kind in ("low", "high"):
        for coupled in (False, True):
            fams.append(("H1(e) target coverage, matched mean", "T_kappa", "low (deficit)",
                         "%s dispersion, %s" % (kind, "physical-coupled (rho_rel, a follow)" if coupled else "kappa only"),
                         lambda m, x, k=kind, c=coupled: fam_cov(m, x, +1, k, c), 0.95))
    for coupled in (False, True):
        fams.append(("H1(e) target coverage, matched mean", "T_kappa", "high (excess)",
                     "under-dispersed {0,1,2}, %s" % ("physical-coupled" if coupled else "kappa only"),
                     lambda m, x, c=coupled: fam_cov(m, x, -1, "low", c), 0.9))
        fams.append(("H1(f) relation-phase yield, matched-mean deficit", "T_rho", "low (rho_rel high)",
                     "high dispersion, physical-coupled (the same deficit read in the relation phase)",
                     lambda m, x, c=coupled: fam_cov(m, x, +1, "high", True), 0.95))

    for rname, (czn, cord, ckob) in regimes.items():
        models = {"ZN": model_values(czn), "ORD": model_values(cord), "KOB": model_values(ckob)}
        base = route({"ZN": None, "ORD": None, "KOB": None}, models)
        out["regimes"][rname] = {
            "compositions": {"ZN": czn, "ORD": cord, "KOB": ckob},
            "f": {k: bc.model_of(models[k])["f"] for k in models},
            "ar_coset": {k: bc.ar_coset(bc.model_of(models[k]))["admitted"] for k in ("ORD", "KOB")},
            "lowest_block_excess": {k: bc.ar_coset(bc.model_of(models[k]))["lowest_block_cycle_excess"]
                                    for k in ("ORD", "KOB")},
            "model_point": base["both"]}
        for (cons, stat, dn, form, fam, xmax) in fams:
            dev, size, firsts = {}, {}, {}
            for k in ("ZN", "ORD", "KOB"):
                m = models[k]
                zn = None if k == "ZN" else models["ZN"]
                if stat == "T_cmp" and k == "ZN":
                    dev[k], size[k] = None, "T_cmp not defined on the control"
                    continue
                x, infeasible_at = smallest_flagged(m, fam, stat, zn, xmax)
                if x is None:
                    dev[k] = None
                    size[k] = "NOT FLAGGED within the feasible range (largest feasible x = %s)" % infeasible_at
                    continue
                w = fam(m, x)
                dev[k] = w
                xf, which = first_flag(m, fam, zn, xmax)
                firsts[k] = {"x_first_any_gate": xf, "first_gates": which}
                size[k] = {"x": x, "kappa_hat": w["kappa_hat"], "kappa_pred": m["kappa_hat"],
                           "z_kappa": bc.kappa_z(w, bc.model_of(w)), "delta_hat": w["delta_hat"],
                           "u_hat": w["u_hat"], "a_bar": w["a_bar"], "rho_rel": w["rho_rel"],
                           "KR": w["KR"], "FR": w["FR"], "d_sigma": w["d_sigma"]}
            r = route(dev, models)
            out["rows"].append({"regime": rname, "consequence": cons, "statistic": stat, "direction": dn,
                                "form": form, "size": size, "first_flag": firsts, "routing": r})
    # PASS-routed edge of target coverage: z_kappa = -3.3 exactly (just inside)
    out["finished_utc"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    json.dump(out, open(S + "/fp_sweep2_out.json", "w"), indent=1, default=str)
    npos = 0
    for r in out["rows"]:
        cells = []
        for cfg in ("both", "ord_only", "kob_only", "control_only"):
            x = r["routing"][cfg]
            dev_present = {"both": ("ORD", "KOB"), "ord_only": ("ORD",), "kob_only": ("KOB",),
                           "control_only": ("ZN",)}[cfg]
            flagged = any(isinstance(r["size"].get(k), dict) for k in dev_present)
            mark = ""
            if x["contract"] == "POSITIVE" and flagged:
                mark = "  <<< FALSE PASS"
                npos += 1
            cells.append("%s %s/%s/%s %s%s" % (cfg, x["class"]["ORD"], x["class"]["KOB"], x["class"]["ZN"],
                                               (x["contract"] + "[" + str(x["H1"]) + "]") if flagged else "(no flagged deviation)", mark))
        print("%-10s %-44s %-10s %-20s %s" % (r["regime"], r["consequence"][:44], r["statistic"],
                                              r["direction"][:20], r["form"][:70]))
        for k in ("ZN", "ORD", "KOB"):
            s = r["size"].get(k)
            if isinstance(s, dict):
                print("      %s x=%.5g z_k=%.3f first=%s" % (k, s["x"], s["z_kappa"],
                                                               r["first_flag"].get(k, {}).get("first_gates")))
            else:
                print("      %s %s" % (k, s))
        print("      " + " | ".join(cells))
    for rn, rr in out["regimes"].items():
        print("REGIME", rn, "f", {k: round(v, 5) for k, v in rr["f"].items()}, "AR-COSET admitted", rr["ar_coset"],
              "lowest block excess", {k: round(v, 2) for k, v in rr["lowest_block_excess"].items()},
              "model point", rr["model_point"]["class"], rr["model_point"]["contract"])
    print("rows", len(out["rows"]), "flagged configurations reading POSITIVE:", npos)


if __name__ == "__main__":
    main()

